__device__ __forceinline__ uint32_t cvt_bf16x2_e4m3x2(uint16_t src) {
  uint32_t dst;
#if defined(__CUDACC_VER_MAJOR__) &&                                                            \
    (__CUDACC_VER_MAJOR__ > 13 || (__CUDACC_VER_MAJOR__ == 13 && __CUDACC_VER_MINOR__ >= 2)) && \
    defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 1000)
  asm("cvt.rn.bf16x2.e4m3x2 %0, %1;" : "=r"(dst) : "h"(src));
#else
  uint32_t _f16x2;
  asm("cvt.rn.f16x2.e4m3x2 %0, %1;" : "=r"(_f16x2) : "h"(src));
  uint16_t _h0 = (uint16_t)(_f16x2 & 0xFFFFu);
  uint16_t _h1 = (uint16_t)((_f16x2 >> 16) & 0xFFFFu);
  float _f0;
  float _f1;
  asm("cvt.f32.f16 %0, %1;" : "=f"(_f0) : "h"(_h0));
  asm("cvt.f32.f16 %0, %1;" : "=f"(_f1) : "h"(_h1));
  asm("cvt.rn.bf16x2.f32 %0, %1, %2;" : "=r"(dst) : "f"(_f1), "f"(_f0));
#endif
  return dst;
}

#include <math_constants.h>

__device__ __forceinline__ uint32_t elect_sync() {
  uint32_t pred = 0;
  asm volatile(
      "{\n\t"
      ".reg .pred %%px;\n\t"
      "elect.sync _|%%px, %1;\n\t"
      "@%%px mov.s32 %0, 1;\n\t"
      "}\n"
      : "+r"(pred)
      : "r"(0xFFFFFFFF));
  return pred;
}

__device__ __forceinline__ void mbarrier_init(int mbar_addr, int count) {
  asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" ::"r"(mbar_addr), "r"(count) : "memory");
}

__device__ __forceinline__ void mbarrier_wait_hint(int mbar_addr, int phase,
                                                   uint32_t suspend_time_hint) {
  asm volatile(
      "{\n\t"
      ".reg .pred P1;\n\t"
      ".reg .u32 WAIT_ADDR;\n\t"
      "mov.u32 WAIT_ADDR, %0;\n\t"
      "LAB_WAIT_HINT:\n\t"
      "mbarrier.try_wait.parity.acquire.cta.shared::cta.b64"
      " P1, [WAIT_ADDR], %1, %2;\n\t"
      "@P1 bra.uni DONE_HINT;\n\t"
      "bra.uni LAB_WAIT_HINT;\n\t"
      "DONE_HINT:\n\t"
      "}\n" ::"r"(mbar_addr),
      "r"(phase), "r"(suspend_time_hint)
      : "memory");
}

__device__ __forceinline__ void mbarrier_wait_cluster_hint(int mbar_addr, int phase,
                                                           uint32_t suspend_time_hint) {
  asm volatile(
      "{\n\t"
      ".reg .pred P1;\n\t"
      "LAB_WAIT_CLUSTER_HINT:\n\t"
      "mbarrier.try_wait.parity.acquire.cluster.shared::cta.b64"
      " P1, [%0], %1, %2;\n\t"
      "@P1 bra.uni DONE_CLUSTER_HINT;\n\t"
      "bra.uni LAB_WAIT_CLUSTER_HINT;\n\t"
      "DONE_CLUSTER_HINT:\n\t"
      "}\n" ::"r"(mbar_addr),
      "r"(phase), "r"(suspend_time_hint)
      : "memory");
}

