}

__device__ __forceinline__ float approx_exp2(float x) {
  float y;
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(y) : "f"(x));
  return y;
}

__device__ __forceinline__ float approx_rcp(float x) {
  float y;
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(y) : "f"(x));
  return y;
}

__device__ __forceinline__ float max_noftz(float a, float b) {
  float c;
  asm("max.f32 %0, %1, %2;" : "=f"(c) : "f"(a), "f"(b));
  return c;
}

__device__ __forceinline__ float row_max_reduce(float2 acc) { return max_noftz(acc.x, acc.y); }

__device__ __forceinline__ void row_max_x32_accum(const float* sv, float2& acc) {
#pragma unroll
  for (int j = 0; j < 16; j++) {
    if (j % 2 == 0)
      acc.x = max_noftz(acc.x, max_noftz(sv[j * 2], sv[j * 2 + 1]));
    else
      acc.y = max_noftz(acc.y, max_noftz(sv[j * 2], sv[j * 2 + 1]));
  }
}

__device__ __forceinline__ void fma_f32x2_inplace(float2* a, float2 b, float2 c) {
  unsigned long long r;
  asm("fma.rn.ftz.f32x2 %0, %1, %2, %3;"
      : "=l"(r)
      : "l"(*(unsigned long long*)a), "l"(*(unsigned long long*)&b), "l"(*(unsigned long long*)&c));
  *(unsigned long long*)a = r;
}

__device__ __forceinline__ void mul_f32x2_noftz_inplace(float2* a, float2 b) {
  asm("mul.rn.f32x2 %0, %0, %1;" : "+l"(*(unsigned long long*)a) : "l"(*(unsigned long long*)&b));
}

